mapper.insert:
insert into pm_workflow_definition_version(definition_id,version_no,version_status,graph_json,create_by,create_time)
select #{definition.definitionId},coalesce(max(version_no),0)+1,'DRAFT',#{graphJson},#{definition.createBy},sysdate()
from pm_workflow_definition_version where definition_id=#{definition.definitionId}

mapper.select:
select count(*) from pm_workflow_task t join pm_workflow_instance i on i.instance_id=t.instance_id
where t.task_id=#{taskId} and (i.initiator_user_id=#{userId} or t.acted_by_user_id=#{userId}
  or exists(select 1 from pm_workflow_task_candidate c where c.task_id=t.task_id and c.user_id=#{userId}))
